const r = $input.first().json;
return [{ json: {
  row_number: r.row_number || r.i || 1,
  sujet: r['Sujet'] || '',
  keyword: r['Mot-clé principal'] || '',
  intent: r['Intent'] || 'informationnelle',
  pilier: r['Pilier'] || 'seo'
} }];

const c = $input.first().json;
const sys = `Tu es schoolsWP Brain, agent stratégique de schoolsWP (schoolswp.com).
Ton rôle : analyser l'intention SEO et produire une stratégie éditoriale avant rédaction.
Réponds UNIQUEMENT en JSON valide, sans backticks, sans commentaires.
Clés requises : angle (string — différenciant vs concurrence), opportunite (affilié|formation|lead magnet|agence), audience (string — profil précis), competition (faible|moyen|élevé), points_cles (tableau de 3 strings — obligatoire à couvrir).`;
const msg = `Sujet : ${c.sujet}
Mot-clé : ${c.keyword}
Intent : ${c.intent}
Pilier : ${c.pilier}`;
return [{ json: { ...c, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 800, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Map Columns').first().json;
let brain = { angle: '', opportunite: '', audience: 'freelance WordPress', competition: 'moyen', points_cles: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  brain = JSON.parse(raw);
} catch(e) {}
const sys = `Tu es le Rédacteur SEO de schoolsWP (schoolswp.com).
Rédige un article SEO complet en markdown : 1500-2500 mots, H1 optimisé pour le mot-clé, H2/H3 structurés, introduction accroche (problème → solution), exemples concrets WordPress (Tutor LMS, FluentCRM, WooCommerce, n8n), tableau comparatif si pertinent, CTA naturels (jamais agressifs), conclusion avec 3 points retenus + 1 action.
Règles schoolsWP : tutoiement systématique, voix directe et pédagogique. Mots interdits : disruptif, game changer, scalable, révolutionnaire, hack, incroyable.
Commence directement par le H1. Zéro préambule.`;
const pts = (brain.points_cles || []).join(', ');
const msg = `Keyword cible : ${prev.keyword}
Sujet : ${prev.sujet}
Intent : ${prev.intent}
Angle différenciant : ${brain.angle || 'à définir'}
Audience : ${brain.audience || 'freelance WordPress intermédiaire'}
Points obligatoires : ${pts || 'non précisés'}

Rédige l'article complet maintenant.`;
return [{ json: { ...prev, angle: brain.angle, audience: brain.audience, competition: brain.competition, points_cles: pts, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 8000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse Brain').first().json;
const v1 = $input.first().json.content[0].text;
const sys = `Tu es l'Auditeur SEO de schoolsWP.
Audite l'article reçu selon 4 dimensions (score /10 chacune) :
1. Sémantique : couverture du champ lexical, entités clés, synonymes
2. Exemples : concrets, vérifiables, propres à schoolsWP
3. Structure : FAQ potentielle, H2/H3, lisibilité, CTA
4. Maillage : ancres naturelles, opportunités liens internes

Score global = moyenne des 4.
Réponds UNIQUEMENT en JSON valide sans backticks.
Clés : score_semantique, score_exemples, score_structure, score_maillage, score_global, points_forts (tableau), points_faibles (tableau), recommandations (tableau).`;
const msg = `Mot-clé : ${prev.keyword}

${v1}`;
return [{ json: { ...prev, v1, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1500, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse V1').first().json;
let audit = { score_global: 7, score_semantique: 7, score_exemples: 7, score_structure: 7, score_maillage: 7, recommandations: [] };
try {
  const raw = $input.first().json.content[0].text.replace(/```json\s*|```\s*/g, '').trim();
  audit = JSON.parse(raw);
} catch(e) {}
const score = typeof audit.score_global === 'number' ? audit.score_global : 7;
const reco = (audit.recommandations || []).join(' | ');
const sys = `Tu es l'Éditeur Senior de schoolsWP.\nTu reçois un article V1 avec son score d'audit global (sur 10) et ses recommandations.\n- Si score >= 7 : retourne l'article exactement tel quel, sans aucune modification.\n- Si score < 7 : améliore l'article en appliquant les recommandations. Conserve la structure. Renforce les sections faibles.\nCommence directement par le H1. Aucun commentaire préliminaire.`;
const msg = `Score audit : ${score}/10\nRecommandations : ${reco || 'aucune'}\n\n--- ARTICLE V1 ---\n\n${prev.v1}`;
return [{ json: { ...prev, score, score_semantique: audit.score_semantique, score_exemples: audit.score_exemples, score_structure: audit.score_structure, score_maillage: audit.score_maillage, recommandations: reco, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 8000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse Audit').first().json;
const v2 = $input.first().json.content[0].text;
const sys = `Tu es le SERP Simulator de schoolsWP.
Simule les 5 premiers résultats Google France pour ce mot-clé.
Fournis :
- Type de contenu dominant (guide/comparatif/tutoriel/liste)
- Angle éditorial majoritaire sur la SERP
- Ce que schoolsWP peut faire MIEUX ou DIFFÉREMMENT
- 3 questions PAA (People Also Ask) inférées
- Niveau de concurrence perçu
Format markdown structuré. 300-500 mots.`;
const msg = `Mot-clé : ${prev.keyword}
Intent : ${prev.intent}
Pilier schoolsWP : ${prev.pilier}`;
return [{ json: { ...prev, v2, working_version: v2, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1500, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse V2').first().json;
const serp = $input.first().json.content[0].text;
const sys = `Tu es l'Optimiseur LLM-SEO de schoolsWP.
Optimise cet article pour être cité par les LLMs (Claude, ChatGPT, Perplexity, Gemini) qui cherchent des sources de référence :
1. Ajoute un encadré "Réponse rapide" (60 mots max) immédiatement après le H1
2. Ajoute un encadré "Définition" pour le concept principal de l'article
3. Termine l'article par une section "Ce qu'il faut retenir" (5 bullet points clés)
4. Assure-toi que chaque H2 commence par une réponse directe à sa question implicite
Conserve intégralement le contenu existant. Commence directement par le H1.`;
const msg = `Article à optimiser (mot-clé : ${prev.keyword}) :

${prev.working_version}`;
return [{ json: { ...prev, serp_analysis: serp, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 10000, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse SERP').first().json;
const v3 = $input.first().json.content[0].text;
const sys = `Tu es le Stratège de Maillage Interne de schoolsWP.
Propose 6-10 opportunités de liens internes pour l'article reçu.
Piliers schoolsWP : SEO WordPress / LMS WordPress / CRM WordPress / Performance / Automatisation.
Format : tableau markdown avec colonnes Ancre | URL relative | Pilier | Pertinence /5.
Angle : ancres naturelles intégrées dans le contexte, jamais artificielles.
Seulement des liens vers des pages qui pourraient raisonnablement exister sur schoolswp.com.`;
const msg = `Article (mot-clé : ${prev.keyword}, pilier : ${prev.pilier}) :

${v3}`;
return [{ json: { ...prev, v3, requestBody: { model: 'claude-sonnet-4-6', max_tokens: 1500, system: sys, messages: [{ role: 'user', content: msg }] } } }];

const prev = $('Code - Parse V3').first().json;
const links = $input.first().json.content[0].text;
const now = new Date().toISOString().split('T')[0];
const scoreLabel = prev.score >= 8 ? 'A' : (prev.score >= 6 ? 'B' : 'C');
const docTitle = `[schoolsWP] ${prev.keyword} — Score ${prev.score}/10 (${now})`;
const finalContent = `${prev.v3}

---

## Maillage interne suggéré

${links}

---

## Analyse SERP

${prev.serp_analysis || 'N/D'}

---

*Généré par Content Machine schoolsWP — ${now} — Score audit : ${prev.score}/10 (Priorité ${scoreLabel})*`;
return [{ json: { ...prev, links_md: links, doc_title: docTitle, final_content: finalContent, priority: scoreLabel, generated_at: now } }];

const prev = $('Code - Assemble').first().json;
const docId = $input.first().json.documentId || '';
const batchUpdateBody = {
  requests: [{
    insertText: {
      location: { index: 1 },
      text: prev.final_content
    }
  }]
};
return [{ json: { ...prev, documentId: docId, batchUpdateBody } }];

const prev = $('Code - Prepare Doc Update').first().json;
const docUrl = prev.documentId ? `https://docs.google.com/document/d/${prev.documentId}/edit` : 'N/D';
return [{ json: {
  'Sujet': prev.sujet,
  'Mot-clé principal': prev.keyword,
  'Statut': 'Généré ✓',
  'Priorité': prev.priority,
  'Score ROI': String(prev.score),
  'Lien Google Doc': docUrl
} }];
